std::string ConvertMarkdownToHtml(const std::string& markdown) {
    // Create stringstream object
    std::stringstream ss;

    // Output the heading tags for HTML
    // We're only handling headers, not subheaders
    ss << "<h1>" << markdown << "</h1>\n";

    return ss.str();  // Returns the converted string
